const P = {"tool": "Combustion and Reaction Modeling Toolkit", "nodes": 17, "steps": 46};

function demoMain(P){
  var N=P.nodes, steps=P.steps, alpha=1.0, dx=1/(N-1), dt=0.4*dx*dx/alpha;
  var T=new Array(N).fill(0); T[0]=100; T[N-1]=0;
  for(var s=0;s<steps;s++){ var Tn=T.slice(); for(var i=1;i<N-1;i++) Tn[i]=T[i]+alpha*dt/(dx*dx)*(T[i+1]-2*T[i]+T[i-1]); T=Tn; }
  var mid=T[Math.floor(N/2)].toFixed(2);
  return 'Heat diffusion ('+P.tool+'): nodes='+N+' steps='+steps+' dt='+dt.toExponential(2)+'s mid-rod='+mid+'C stable='+String(dt<=0.5*dx*dx/alpha)+' (explicit scheme CFL check)';
}
console.log(demoMain(P));

